import{c as l,Q as o,j as e,m as a}from"./chunks/framework.DOi4mjdC.js";const g="/assets/Ascend-C-API%E5%B1%82%E6%AC%A1%E7%BB%93%E6%9E%84.UQ4nxDlc.png",A=JSON.parse('{"title":"Ascend C API 兼容性策略","description":"","frontmatter":{},"headers":[{"level":1,"title":"Ascend C API 兼容性策略","slug":"ascend-c-api-兼容性策略"}],"relativePath":"guide/跨代迁移兼容性指南/Ascend-C-API兼容策略.md","filePath":"guide/跨代迁移兼容性指南/Ascend-C-API兼容策略.md"}'),d={name:"guide/跨代迁移兼容性指南/Ascend-C-API兼容策略.md"};function u(r,t,s,q,c,n){return o(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="ascend-c-api-兼容性策略" tabindex="-1">Ascend C API 兼容性策略 <a class="header-anchor" href="#ascend-c-api-兼容性策略" aria-label="Permalink to &quot;Ascend C API 兼容性策略&quot;">​</a></h1><p>本兼容性说明仅适用于Ascend C算子开发的兼容性迁移指导。总体兼容性策略见<a href="#table18109729593">表1</a>，兼容性范围不包含编译器BuiltIn API、Ascend C内部实现接口等。文档中涉及的兼容性分为两类：一是功能兼容，包括数据类型兼容、接口原型兼容和常量兼容；二是性能兼容，指对于同等数据量，新架构上执行API耗时不高于旧架构。</p><p>若开发者希望在<a href="./../编程指南/语言扩展层/SIMD-BuiltIn关键字.html#table65291052154114">NPU架构版本3510</a>下运行原本在<a href="./../编程指南/语言扩展层/SIMD-BuiltIn关键字.html#table65291052154114">NPU架构版本2201</a>上开发的Ascend C程序，需在3510架构上重新编译并运行，并可能需要根据迁移指导进行代码调整。</p><p><strong>图 1</strong> Ascend C API层次结构<br><img src="'+g+'" alt="" title="Ascend-C-API层次结构"></p><p><strong>表 1</strong> Ascend C API兼容策略</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;18.01%&quot;&gt;&lt;p&gt;API层级&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;81.99%&quot;&gt;&lt;p&gt;兼容策略&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;18.01%&quot;&gt;&lt;p&gt;高阶API&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;81.99%&quot;&gt;&lt;p&gt;高阶API在同领域内可保证兼容，特定领域扩展特性不保证兼容。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;18.01%&quot;&gt;&lt;p&gt;基础API&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;81.99%&quot;&gt;&lt;p&gt;基础API分为可兼容的基础API和ISASI基础API；兼容的API在所有架构上均能兼容；ISASI API为体系架构相关的API，不保证跨架构版本的兼容性，例如CUBE侧的计算接口LoadData、Mmad等。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;18.01%&quot;&gt;&lt;p&gt;语言扩展层C API&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;81.99%&quot;&gt;&lt;p&gt;SIMD &amp; SIMT C API可分为兼容性API和体系架构相关API；当前SIMD的C API仅支持体系架构相关，暂未支持跨代兼容。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;18.01%&quot;&gt;&lt;p&gt;编译器BuiltIn API&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;81.99%&quot;&gt;&lt;p&gt;不保证兼容。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p>',6)])])}const i=l(d,[["render",u]]);export{A as __pageData,i as default};
